import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';

const QuickActions = ({ onStartSession, onJoinCollaborative, onAccessAR, themeColors }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [selectedAction, setSelectedAction] = useState(null);

  const quickActions = [
    {
      id: 'start-session',
      title: 'Start Learning',
      description: 'Begin an AI-adaptive session',
      icon: 'Play',
      color: themeColors.primary,
      action: onStartSession,
      route: '/interactive-learning-session'
    },
    {
      id: 'collaborative',
      title: 'Join Group',
      description: 'Collaborative learning session',
      icon: 'Users',
      color: themeColors.secondary,
      action: onJoinCollaborative,
      route: '/interactive-learning-session?mode=collaborative'
    },
    {
      id: 'ar-mode',
      title: 'AR Experience',
      description: 'Immersive 3D learning',
      icon: 'Glasses',
      color: themeColors.accent,
      action: onAccessAR,
      route: '/interactive-learning-session?mode=ar'
    },
    {
      id: 'analytics',
      title: 'View Progress',
      description: 'Check your learning analytics',
      icon: 'BarChart3',
      color: '#10B981',
      action: null,
      route: '/progress-analytics-dashboard'
    }
  ];

  const handleActionClick = (action) => {
    setSelectedAction(action.id);
    if (action.action) {
      action.action();
    }
    setTimeout(() => setSelectedAction(null), 200);
  };

  return (
    <div className="fixed bottom-20 right-4 z-40 lg:bottom-6 lg:right-6">
      {/* Main Action Button */}
      <div className="relative">
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className={`w-14 h-14 rounded-full shadow-warm-lg transition-all duration-300 flex items-center justify-center ${
            isExpanded 
              ? 'bg-error text-white rotate-45' :'bg-primary text-white hover:scale-110'
          }`}
          style={{ backgroundColor: isExpanded ? '#EF4444' : themeColors.primary }}
        >
          <Icon name={isExpanded ? "X" : "Zap"} size={24} />
        </button>

        {/* Floating Action Buttons */}
        {isExpanded && (
          <div className="absolute bottom-16 right-0 space-y-3 animate-fade-in">
            {quickActions.map((action, index) => (
              <div
                key={action.id}
                className="flex items-center space-x-3 animate-slide-up"
                style={{ animationDelay: `${index * 0.1}s` }}
              >
                {/* Action Label */}
                <div className="bg-surface border border-border rounded-lg px-3 py-2 shadow-warm-md opacity-0 animate-fade-in hidden lg:block"
                     style={{ animationDelay: `${(index * 0.1) + 0.2}s`, animationFillMode: 'forwards' }}>
                  <div className="text-right">
                    <p className="text-sm font-medium text-text-primary">{action.title}</p>
                    <p className="text-xs text-text-secondary">{action.description}</p>
                  </div>
                </div>

                {/* Action Button */}
                {action.route ? (
                  <Link
                    to={action.route}
                    onClick={() => handleActionClick(action)}
                    className={`w-12 h-12 rounded-full shadow-warm-md transition-all duration-200 flex items-center justify-center text-white hover:scale-110 active:scale-95 ${
                      selectedAction === action.id ? 'scale-95' : ''
                    }`}
                    style={{ backgroundColor: action.color }}
                  >
                    <Icon name={action.icon} size={20} />
                  </Link>
                ) : (
                  <button
                    onClick={() => handleActionClick(action)}
                    className={`w-12 h-12 rounded-full shadow-warm-md transition-all duration-200 flex items-center justify-center text-white hover:scale-110 active:scale-95 ${
                      selectedAction === action.id ? 'scale-95' : ''
                    }`}
                    style={{ backgroundColor: action.color }}
                  >
                    <Icon name={action.icon} size={20} />
                  </button>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Pulse Animation for Main Button */}
        {!isExpanded && (
          <div 
            className="absolute inset-0 rounded-full animate-ping opacity-20"
            style={{ backgroundColor: themeColors.primary }}
          ></div>
        )}
      </div>

      {/* Quick Stats Overlay */}
      {!isExpanded && (
        <div className="absolute -top-16 right-0 bg-surface border border-border rounded-lg px-3 py-2 shadow-warm-md opacity-0 hover:opacity-100 transition-opacity duration-200 pointer-events-none">
          <div className="text-center">
            <p className="text-xs font-medium text-text-primary">Ready to learn</p>
            <p className="text-xs text-text-secondary">3 topics pending</p>
          </div>
        </div>
      )}

      {/* Background Overlay for Mobile */}
      {isExpanded && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-20 -z-10 lg:hidden"
          onClick={() => setIsExpanded(false)}
        ></div>
      )}
    </div>
  );
};

export default QuickActions;