import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Icon from 'components/AppIcon';

const SessionPanel = ({ session, onEndSession, themeColors }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [displayTime, setDisplayTime] = useState('00:00');

  useEffect(() => {
    if (session.isActive) {
      const interval = setInterval(() => {
        const minutes = Math.floor(session.duration / 60);
        const seconds = session.duration % 60;
        setDisplayTime(`${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`);
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [session.duration, session.isActive]);

  if (!session.isActive && !isExpanded) {
    return (
      <div className="fixed bottom-4 left-1/2 transform -translate-x-1/2 z-30">
        <button
          onClick={() => setIsExpanded(true)}
          className="bg-surface border border-border rounded-full px-6 py-3 shadow-warm-lg hover:shadow-warm-xl transition-all duration-200 hover:scale-105"
        >
          <div className="flex items-center space-x-3">
            <Icon name="Play" size={18} className="text-primary" />
            <span className="font-medium text-text-primary">Start Learning Session</span>
          </div>
        </button>
      </div>
    );
  }

  return (
    <div className={`fixed bottom-0 left-0 right-0 z-30 bg-surface border-t border-border shadow-warm-xl transition-all duration-300 ${
      isExpanded ? 'h-auto' : 'h-16'
    }`}>
      <div className="max-w-7xl mx-auto px-4">
        {/* Collapsed Header */}
        <div 
          className="flex items-center justify-between h-16 cursor-pointer"
          onClick={() => setIsExpanded(!isExpanded)}
        >
          <div className="flex items-center space-x-4">
            {session.isActive ? (
              <>
                <div className="flex items-center space-x-2">
                  <div className="w-3 h-3 bg-success rounded-full animate-pulse"></div>
                  <span className="font-medium text-text-primary">Active Session</span>
                </div>
                <div className="hidden sm:flex items-center space-x-4 text-sm text-text-secondary">
                  <span>{displayTime}</span>
                  <span>•</span>
                  <span>{session.currentTopic}</span>
                </div>
              </>
            ) : (
              <div className="flex items-center space-x-2">
                <Icon name="Play" size={18} className="text-primary" />
                <span className="font-medium text-text-primary">Ready to Learn</span>
              </div>
            )}
          </div>

          <div className="flex items-center space-x-2">
            {session.isActive && (
              <div className="hidden sm:flex items-center space-x-4 text-sm">
                <div className="flex items-center space-x-1">
                  <Icon name="Target" size={14} className="text-text-secondary" />
                  <span className="text-text-secondary">{session.topicsCompleted}/5</span>
                </div>
                <div className="flex items-center space-x-1">
                  <Icon name="Flame" size={14} className="text-accent" />
                  <span className="text-text-secondary">{session.streak}</span>
                </div>
              </div>
            )}
            <Icon 
              name={isExpanded ? "ChevronDown" : "ChevronUp"} 
              size={20} 
              className="text-text-secondary" 
            />
          </div>
        </div>

        {/* Expanded Content */}
        {isExpanded && (
          <div className="pb-6 animate-fade-in">
            {session.isActive ? (
              // Active Session Content
              <div className="space-y-6">
                {/* Session Stats */}
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
                  <div className="bg-surface-50 rounded-lg p-4 text-center">
                    <div className="text-2xl font-heading font-bold text-text-primary mb-1">
                      {displayTime}
                    </div>
                    <div className="text-sm text-text-secondary">Session Time</div>
                  </div>
                  <div className="bg-surface-50 rounded-lg p-4 text-center">
                    <div className="text-2xl font-heading font-bold text-text-primary mb-1">
                      {session.topicsCompleted}
                    </div>
                    <div className="text-sm text-text-secondary">Topics Done</div>
                  </div>
                  <div className="bg-surface-50 rounded-lg p-4 text-center">
                    <div className="text-2xl font-heading font-bold text-text-primary mb-1">
                      {session.todayProgress}%
                    </div>
                    <div className="text-sm text-text-secondary">Today's Progress</div>
                  </div>
                  <div className="bg-surface-50 rounded-lg p-4 text-center">
                    <div className="text-2xl font-heading font-bold text-text-primary mb-1">
                      {session.streak}
                    </div>
                    <div className="text-sm text-text-secondary">Day Streak</div>
                  </div>
                  <div className="bg-surface-50 rounded-lg p-4 text-center border-l-4 border-accent">
                    <div className="text-2xl font-heading font-bold text-text-primary mb-1 flex items-center justify-center gap-1">
                      <Icon name="Award" size={20} className="text-accent" />
                      <span>{session.elo || 1000}</span>
                    </div>
                    <div className="text-sm text-text-secondary">AI ELO Rating</div>
                  </div>
                </div>

                {/* Current Topic */}
                <div className="bg-gradient-to-r from-primary-50 to-secondary-50 rounded-lg p-4">
                  <div className="flex items-center justify-between">
                    <div>
                      <h3 className="font-heading font-semibold text-text-primary mb-1">
                        Currently Learning
                      </h3>
                      <p className="text-text-secondary">{session.currentTopic}</p>
                    </div>
                    <Link
                      to="/interactive-learning-session"
                      className="btn btn-primary px-6 py-2"
                    >
                      Continue
                    </Link>
                  </div>
                </div>

                {/* Session Controls */}
                <div className="flex flex-wrap gap-3">
                  <button
                    onClick={onEndSession}
                    className="btn bg-error text-white hover:bg-error-600 px-4 py-2"
                  >
                    <Icon name="Square" size={16} className="mr-2" />
                    End Session
                  </button>
                  <button className="btn btn-outline px-4 py-2">
                    <Icon name="Pause" size={16} className="mr-2" />
                    Take Break
                  </button>
                  <button className="btn btn-outline px-4 py-2">
                    <Icon name="Users" size={16} className="mr-2" />
                    Invite Friend
                  </button>
                  <button className="btn btn-outline px-4 py-2">
                    <Icon name="Glasses" size={16} className="mr-2" />
                    AR Mode
                  </button>
                </div>
              </div>
            ) : (
              // Start Session Content
              <div className="space-y-6">
                {/* Quick Start Options */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <Link
                    to="/interactive-learning-session"
                    className="p-6 bg-gradient-to-br from-primary to-primary-700 rounded-lg text-white hover:scale-105 transition-transform duration-200"
                  >
                    <Icon name="Brain" size={32} className="mb-3" />
                    <h3 className="font-heading font-semibold mb-2">AI Adaptive</h3>
                    <p className="text-sm opacity-90">Let AI create your perfect learning path</p>
                  </Link>
                  
                  <Link
                    to="/interactive-learning-session"
                    className="p-6 bg-gradient-to-br from-secondary to-secondary-700 rounded-lg text-white hover:scale-105 transition-transform duration-200"
                  >
                    <Icon name="Users" size={32} className="mb-3" />
                    <h3 className="font-heading font-semibold mb-2">Collaborative</h3>
                    <p className="text-sm opacity-90">Learn together with peers and AI guidance</p>
                  </Link>
                  
                  <Link
                    to="/interactive-learning-session"
                    className="p-6 bg-gradient-to-br from-accent to-accent-700 rounded-lg text-white hover:scale-105 transition-transform duration-200"
                  >
                    <Icon name="Glasses" size={32} className="mb-3" />
                    <h3 className="font-heading font-semibold mb-2">AR Experience</h3>
                    <p className="text-sm opacity-90">Immersive 3D learning with augmented reality</p>
                  </Link>
                </div>

                {/* Today's Recommendations */}
                <div className="bg-surface-50 rounded-lg p-4">
                  <h3 className="font-heading font-semibold text-text-primary mb-3">
                    AI Recommendations for Today
                  </h3>
                  <div className="space-y-2">
                    <div className="flex items-center justify-between p-3 bg-white rounded border-l-4 border-primary">
                      <div className="flex items-center space-x-3">
                        <Icon name="Calculator" size={16} className="text-primary" />
                        <span className="text-sm font-medium text-text-primary">Continue Linear Equations</span>
                      </div>
                      <span className="text-xs text-text-secondary">15 min</span>
                    </div>
                    <div className="flex items-center justify-between p-3 bg-white rounded border-l-4 border-secondary">
                      <div className="flex items-center space-x-3">
                        <Icon name="Code" size={16} className="text-secondary" />
                        <span className="text-sm font-medium text-text-primary">JavaScript Functions Review</span>
                      </div>
                      <span className="text-xs text-text-secondary">20 min</span>
                    </div>
                    <div className="flex items-center justify-between p-3 bg-white rounded border-l-4 border-accent">
                      <div className="flex items-center space-x-3">
                        <Icon name="Clock" size={16} className="text-accent" />
                        <span className="text-sm font-medium text-text-primary">Ancient Rome AR Tour</span>
                      </div>
                      <span className="text-xs text-text-secondary">25 min</span>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SessionPanel;