import React, { useState, useEffect, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import Icon from 'components/AppIcon';
import api from '../../lib/api';
import { ProgressContext } from '../../contexts/ProgressContext';
import { DataContext } from '../../contexts/DataContext';
import MindMapVisualization from './components/MindMapVisualization';
import SessionPanel from './components/SessionPanel';
import SubjectFilters from './components/SubjectFilters';
import AchievementNotifications from './components/AchievementNotifications';
import LoadingState from '../../components/ui/LoadingState';
import ErrorState from '../../components/ui/ErrorState';
import QuickActions from './components/QuickActions';
import DashboardEmptySlate from './components/DashboardEmptySlate';

const AdaptiveLearningDashboard = () => {
  const progressContext = useContext(ProgressContext) || {};
  const learningNodes = progressContext.learningNodes || [];
  const progressLoading = progressContext.loading || false;
  const progressError = progressContext.error || null;
  const resetAllProgress = progressContext.resetAllProgress || (() => {});
  const refreshProgress = progressContext.refreshProgress || (() => {});
  const sessionLogs = progressContext.sessionLogs || [];

  const dataContext = useContext(DataContext) || {};
  const userStats = dataContext.userStats || null;
  const achievements = dataContext.achievements || [];
  const dataLoading = dataContext.loading || false;
  const dataError = dataContext.error || null;
  const refreshData = dataContext.refreshData || (() => {});

  const navigate = useNavigate();

  const [selectedSubject, setSelectedSubject] = useState('all');
  const [difficultyLevel, setDifficultyLevel] = useState('adaptive');
  const [learningStyle, setLearningStyle] = useState('visual');
  const [showSidebar, setShowSidebar] = useState(false);
  const [currentTheme, setCurrentTheme] = useState('dynamic');
  const [seedingCatalog, setSeedingCatalog] = useState(false);

  const activeNode =
    learningNodes.find((n) => n.status === 'in-progress') || learningNodes.find((n) => !n.completed);
  const latestSession = sessionLogs[0];

  const currentSession = {
    isActive: Boolean(activeNode),
    duration: latestSession?.durationSeconds || 0,
    topicsCompleted: learningNodes.filter((n) => n.completed).length,
    currentTopic: activeNode?.title || latestSession?.topic || 'Start a module',
    streak: userStats?.streak || 0,
    todayProgress: userStats?.completionRate || 0,
    elo: userStats?.elo || 1000,
  };

  const userMood =
    userStats?.completionRate >= 50 ? 'focused' : userStats?.completionRate > 0 ? 'engaged' : 'curious';

  const subjects = [
    { id: 'all', name: 'All Subjects', icon: 'BookOpen', color: 'primary' },
    { id: 'mathematics', name: 'Mathematics', icon: 'Calculator', color: 'secondary' },
    { id: 'programming', name: 'Programming', icon: 'Code', color: 'accent' },
    { id: 'history', name: 'History', icon: 'Clock', color: 'success' },
  ];

  useEffect(() => {
    const updateTheme = () => {
      const hour = new Date().getHours();
      let theme = 'dynamic';
      if (hour >= 6 && hour < 12) theme = 'morning';
      else if (hour >= 12 && hour < 18) theme = 'afternoon';
      else if (hour >= 18 && hour < 22) theme = 'evening';
      else theme = 'night';
      setCurrentTheme(theme);
    };
    updateTheme();
    const interval = setInterval(updateTheme, 60000);
    return () => clearInterval(interval);
  }, []);

  const getThemeColors = () => {
    const themes = {
      morning: { primary: '#F59E0B', secondary: '#10B981', accent: '#3B82F6' },
      afternoon: { primary: '#EF4444', secondary: '#F59E0B', accent: '#8B5CF6' },
      evening: { primary: '#8B5CF6', secondary: '#EC4899', accent: '#F59E0B' },
      night: { primary: '#1F2937', secondary: '#374151', accent: '#6B7280' },
      dynamic: { primary: '#4F46E5', secondary: '#06B6D4', accent: '#F59E0B' },
    };
    return themes[currentTheme] || themes.dynamic;
  };

  const handleRetry = () => {
    refreshProgress();
    refreshData();
  };

  const filteredNodes =
    selectedSubject === 'all' ? learningNodes : learningNodes.filter((node) => node.subject === selectedSubject);

  const handleNodeSelect = (nodeId) => {
    const node = learningNodes.find((n) => n.id === nodeId);
    if (node) {
      navigate(`/interactive-learning-session/${nodeId}`);
    }
  };

  const handleEnableCatalog = async () => {
    setSeedingCatalog(true);
    try {
      await api.seedCatalog();
      await refreshProgress();
    } catch (err) {
      console.error(err);
    } finally {
      setSeedingCatalog(false);
    }
  };

  const handleStartSession = () => {
    if (activeNode) {
      navigate(`/interactive-learning-session/${activeNode.id}`);
    } else {
      navigate('/learn');
    }
  };

  return (
    <div className="min-h-screen bg-background relative overflow-hidden">
      <div className="absolute inset-0 overflow-hidden pointer-events-none" aria-hidden="true">
        <div
          className="absolute top-20 left-10 w-32 h-32 rounded-full opacity-10 animate-pulse"
          style={{ backgroundColor: getThemeColors().primary }}
        />
        <div
          className="absolute bottom-20 right-20 w-24 h-24 rounded-full opacity-10 animate-pulse"
          style={{ backgroundColor: getThemeColors().secondary }}
        />
      </div>

      {showSidebar && (
        <button
          type="button"
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
          onClick={() => setShowSidebar(false)}
          aria-label="Close sidebar"
        />
      )}

      <div
        className={`fixed left-0 top-0 bottom-0 w-72 sm:w-80 bg-surface border-r border-border shadow-warm-lg transform transition-transform duration-300 z-50 ${
          showSidebar ? 'translate-x-0' : '-translate-x-full'
        } lg:translate-x-0 lg:static lg:h-auto lg:shadow-none lg:border-r-0 lg:pt-16`}
      >
        <div className="h-full lg:fixed lg:w-72 lg:top-16 lg:bottom-0 lg:border-r lg:border-border overflow-y-auto">
          <SubjectFilters
            subjects={subjects}
            selectedSubject={selectedSubject}
            onSubjectChange={setSelectedSubject}
            difficultyLevel={difficultyLevel}
            onDifficultyChange={setDifficultyLevel}
            learningStyle={learningStyle}
            onLearningStyleChange={setLearningStyle}
            currentTheme={currentTheme}
            userMood={userMood}
          />
        </div>
      </div>

      <div className="flex-1 lg:ml-72 pt-16">
        <button
          type="button"
          onClick={() => setShowSidebar(true)}
          className="lg:hidden fixed top-20 left-4 z-30 p-2 bg-surface border border-border rounded-lg shadow-warm-sm text-text-primary hover:bg-surface-50"
          aria-label="Open filters"
        >
          <Icon name="Menu" size={20} />
        </button>

        {progressLoading || dataLoading ? (
          <LoadingState message="Loading learning map..." fullScreen />
        ) : progressError || dataError ? (
          <ErrorState
            title="Could not load dashboard"
            message={progressError || dataError}
            onRetry={handleRetry}
          />
        ) : (
          <div className="relative h-[calc(100vh-4rem)]">
            {filteredNodes.length === 0 && (
              <DashboardEmptySlate onEnableCatalog={handleEnableCatalog} seeding={seedingCatalog} />
            )}
            <MindMapVisualization
              nodes={filteredNodes}
              onNodeSelect={handleNodeSelect}
              themeColors={getThemeColors()}
              userMood={userMood}
              learningStyle={learningStyle}
            />
            <QuickActions onStartSession={handleStartSession} themeColors={getThemeColors()} />
          </div>
        )}
      </div>

      <SessionPanel session={currentSession} onEndSession={() => {}} themeColors={getThemeColors()} />
      <AchievementNotifications achievements={achievements} themeColors={getThemeColors()} />

      {import.meta.env.DEV && (
        <button
          type="button"
          onClick={resetAllProgress}
          className="fixed bottom-4 right-4 z-50 bg-error text-white p-2 rounded-lg shadow-lg hover:bg-error-700 transition-colors text-xs"
          title="Reset All Learning Progress (Dev Only)"
        >
          <Icon name="RotateCcw" size={16} className="mr-1 inline-block" /> Reset Progress
        </button>
      )}

      <div className="fixed top-20 right-4 sm:right-6 lg:right-8 z-30">
        <div className="bg-surface border border-border rounded-full px-3 py-1.5 sm:px-4 sm:py-2 shadow-warm-sm">
          <span className="text-xs sm:text-sm font-caption text-text-secondary capitalize">{userMood} mode</span>
        </div>
      </div>
    </div>
  );
};

export default AdaptiveLearningDashboard;
