import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import Icon from 'components/AppIcon';

const MindMapVisualization = ({ 
  nodes = [], 
  onNodeSelect, 
  themeColors, 
  userMood, 
  learningStyle 
}) => {
  const svgRef = useRef();
  const containerRef = useRef();
  const [selectedNode, setSelectedNode] = useState(null);
  const [hoveredNode, setHoveredNode] = useState(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 600 });
  const [zoomLevel, setZoomLevel] = useState(1);
  const [viewMode, setViewMode] = useState('clustered'); // 'clustered' or 'overview'

  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        setDimensions({ width: width || 800, height: height || 600 });
      }
    };

    updateDimensions();
    window.addEventListener('resize', updateDimensions);
    return () => window.removeEventListener('resize', updateDimensions);
  }, []);

  useEffect(() => {
    if (!nodes.length || !svgRef.current) return;

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const { width, height } = dimensions;

    // Create zoom behavior with filtered events to avoid conflicts with node interactions
    const zoom = d3.zoom()
      .scaleExtent([0.3, 4])
      .filter((event) => {
        // Prevent zoom on node elements to allow clicking
        const isNodeElement = event.target.closest('.node-group');
        return !isNodeElement;
      })
      .on('zoom', (event) => {
        container.attr('transform', event.transform);
        setZoomLevel(event.transform.k);
      });

    svg.call(zoom);

    const container = svg.append('g');

    // Group nodes by subject for clustering
    const nodesBySubject = groupNodesBySubject(nodes);
    const subjectCenters = calculateSubjectCenters(nodesBySubject, width, height, viewMode);
    
    // Ensure all nodes have valid initial positions
    nodes.forEach(node => {
      if (!node.x || !node.y) {
        const center = subjectCenters[node.subject] || { x: width / 2, y: height / 2 };
        node.x = center.x + (Math.random() - 0.5) * 100;
        node.y = center.y + (Math.random() - 0.5) * 100;
      }
    });
    
    // Create enhanced force simulation with better clustering for overview mode
    const simulation = d3.forceSimulation(nodes)
      .force('link', d3.forceLink().id(d => d.id).distance(d => {
        if (viewMode === 'overview') {
          // Shorter distances in overview mode for tighter clustering
          return d.source.subject === d.target.subject ? 40 : 80;
        }
        // Original distances for clustered mode
        return d.source.subject === d.target.subject ? 60 : 120;
      }))
      .force('charge', d3.forceManyBody().strength(d => {
        if (viewMode === 'overview') {
          // Weaker repulsion in overview mode for tighter packing
          return d.completed ? -200 : -150;
        }
        // Stronger repulsion for completed nodes to spread them out
        return d.completed ? -400 : -300;
      }))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(d => {
        if (viewMode === 'overview') {
          // Smaller collision radius in overview mode
          return d.difficulty === 'advanced' ? 35 : 30;
        }
        // Larger collision radius for advanced topics
        return d.difficulty === 'advanced' ? 60 : 50;
      }))
      .force('cluster', forceCluster(subjectCenters, viewMode));

    // Create enhanced links data with subject relationships
    const links = createEnhancedLinks(nodes);

    // Draw subject area backgrounds
    drawSubjectAreas(container, subjectCenters, themeColors);

    // Draw enhanced connections
    const link = container.append('g')
      .selectAll('path')
      .data(links)
      .enter()
      .append('path')
      .attr('fill', 'none')
      .attr('stroke', d => getConnectionColor(d, themeColors))
      .attr('stroke-opacity', d => d.type === 'prerequisite' ? 0.6 : 0.3)
      .attr('stroke-width', d => d.type === 'prerequisite' ? 3 : 2)
      .attr('marker-end', d => d.type === 'prerequisite' ? 'url(#arrowhead)' : null)
      .style('filter', 'drop-shadow(0 0 3px rgba(79, 70, 229, 0.3))');

    // Add arrow markers for prerequisites
    svg.append('defs').append('marker')
      .attr('id', 'arrowhead')
      .attr('viewBox', '0 -5 10 10')
      .attr('refX', 25)
      .attr('refY', 0)
      .attr('markerWidth', 6)
      .attr('markerHeight', 6)
      .attr('orient', 'auto')
      .append('path')
      .attr('d', 'M0,-5L10,0L0,5')
      .attr('fill', themeColors.primary);

    // Create enhanced node groups
    const nodeGroup = container.append('g')
      .selectAll('g')
      .data(nodes)
      .enter()
      .append('g')
      .attr('class', 'node-group')
      .style('cursor', 'pointer')
      .style('pointer-events', 'all')
      .call(d3.drag()
        .on('start', dragstarted)
        .on('drag', dragged)
        .on('end', dragended));

    // Add enhanced node visualization
    nodeGroup.each(function(d) {
      const group = d3.select(this);
      
      // Outer glow for active nodes
      if (d.status === 'in-progress') {
        group.append('circle')
          .attr('r', 35)
          .attr('fill', 'none')
          .attr('stroke', themeColors.accent)
          .attr('stroke-width', 2)
          .attr('opacity', 0.3)
          .style('animation', 'pulse 2s infinite');
      }
      
      // Main node circle with enhanced styling
      group.append('circle')
        .attr('r', d => getNodeRadius(d))
        .attr('fill', d => getNodeFill(d, themeColors))
        .attr('stroke', d => getNodeStroke(d, themeColors))
        .attr('stroke-width', 3)
        .style('filter', 'drop-shadow(0 4px 12px rgba(0, 0, 0, 0.15))')
        .style('transition', 'all 0.3s ease');

      // Multi-layer progress visualization
      if (!d.completed && d.progress > 0) {
        addProgressVisualization(group, d, themeColors);
      }

      // Enhanced subject icon with better symbols
      const iconInfo = getEnhancedSubjectIcon(d.subject);
      group.append('text')
        .attr('text-anchor', 'middle')
        .attr('dy', '0.35em')
        .attr('font-size', d => d.difficulty === 'advanced' ? '18px' : '16px')
        .attr('fill', d.completed ? 'white' : iconInfo.color)
        .text(iconInfo.symbol);

      // Difficulty indicator with enhanced styling
      addDifficultyIndicator(group, d, themeColors);

      // Progress percentage with better visibility
      if (!d.completed && d.progress > 0) {
        group.append('text')
          .attr('text-anchor', 'middle')
          .attr('dy', '50px')
          .attr('font-size', '11px')
          .attr('font-weight', 'bold')
          .attr('fill', themeColors.primary)
          .attr('opacity', 0.8)
          .text(`${Math.round(d.progress)}%`);
      }

      // Enhanced node title with better wrapping
      addEnhancedTitle(group, d);

      // Time indicator for estimated completion
      if (d.estimatedTime) {
        group.append('text')
          .attr('text-anchor', 'middle')
          .attr('dy', '65px')
          .attr('font-size', '10px')
          .attr('fill', themeColors.secondary)
          .attr('opacity', 0.7)
          .text(d.estimatedTime);
      }

      // Status indicators
      addStatusIndicators(group, d, themeColors);
    });

    // Enhanced interactions with better feedback
    nodeGroup
      .on('mouseenter', function(event, d) {
        setHoveredNode(d);
        enhanceNodeOnHover(d3.select(this), d, themeColors);
        
        // Enhanced highlighting of connected nodes
        const connectedIds = [d.id, ...(d.connections || [])];
        nodeGroup
          .style('opacity', node => connectedIds.includes(node.id) ? 1 : 0.2)
          .filter(node => connectedIds.includes(node.id))
          .select('circle')
          .attr('r', node => getNodeRadius(node) * 1.2);
          
        link.style('opacity', link => 
          link.source.id === d.id || link.target.id === d.id ? 0.9 : 0.05
        );
      })
      .on('mouseleave', function(event, d) {
        setHoveredNode(null);
        resetNodeFromHover(d3.select(this), d);
        nodeGroup.style('opacity', 1).select('circle').attr('r', d => getNodeRadius(d));
        link.style('opacity', d => d.type === 'prerequisite' ? 0.6 : 0.3);
      })
      .on('click', function(event, d) {
        event.stopPropagation();
        if (!d || !d.id) return;
        setSelectedNode(d);

        d3.select(this)
          .select('circle')
          .transition()
          .duration(200)
          .attr('r', getNodeRadius(d) * 1.3)
          .transition()
          .duration(200)
          .attr('r', getNodeRadius(d))
          .on('end', () => {
            onNodeSelect?.(d.id);
          });
      });

    // Enhanced simulation with better positioning
    simulation.on('tick', () => {
      // Curved links for better visualization
      link.attr('d', d => {
        // Ensure we have valid coordinates
        if (!d.source || !d.target || 
            typeof d.source.x !== 'number' || typeof d.source.y !== 'number' ||
            typeof d.target.x !== 'number' || typeof d.target.y !== 'number') {
          return '';
        }
        
        const dx = d.target.x - d.source.x;
        const dy = d.target.y - d.source.y;
        const dr = Math.sqrt(dx * dx + dy * dy) * 0.3;
        return `M${d.source.x},${d.source.y}A${dr},${dr} 0 0,1 ${d.target.x},${d.target.y}`;
      });

      nodeGroup.attr('transform', d => {
        // Ensure we have valid coordinates
        if (typeof d.x !== 'number' || typeof d.y !== 'number') {
          return 'translate(0,0)';
        }
        return `translate(${d.x},${d.y})`;
      });
    });

    // Drag functions with enhanced behavior
    function dragstarted(event, d) {
      if (!event.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    }

    function dragged(event, d) {
      d.fx = event.x;
      d.fy = event.y;
    }

    function dragended(event, d) {
      if (!event.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    }

    return () => {
      simulation.stop();
    };
  }, [nodes, dimensions, themeColors, viewMode]);

  const isEmpty = nodes.length === 0;

  return (
    <div ref={containerRef} className="w-full h-full relative">
      {isEmpty && (
        <div className="absolute inset-0 flex items-center justify-center z-10 pointer-events-none">
          <div className="text-center max-w-md pointer-events-auto">
            <div className="w-20 h-20 mx-auto mb-4 rounded-full flex items-center justify-center" style={{ backgroundColor: themeColors.primary + '15' }}>
              <Icon name="Map" size={36} style={{ color: themeColors.primary }} />
            </div>
            <h3 className="text-lg font-heading font-semibold text-text-primary mb-2">Your Learning Map</h3>
            <p className="text-sm text-text-secondary">Enable the curriculum catalog to populate your mind map with learning nodes.</p>
          </div>
        </div>
      )}
      <svg
        ref={svgRef}
        width={dimensions.width}
        height={dimensions.height}
        className="w-full h-full"
        style={{ pointerEvents: 'auto', opacity: isEmpty ? 0.15 : 1 }}
      >
      </svg>

      {/* Enhanced Node Details Tooltip */}
      {hoveredNode && (
        <div 
          className="absolute z-20 bg-surface border border-border rounded-lg shadow-2xl p-4 pointer-events-none max-w-sm"
          style={{
            left: '50%',
            top: '20px',
            transform: 'translateX(-50%)'
          }}
        >
          <div className="flex items-start space-x-3 mb-3">
            <div 
              className="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0"
              style={{ backgroundColor: themeColors.primary }}
            >
              <span className="text-white text-lg">
                {getEnhancedSubjectIcon(hoveredNode.subject).symbol}
              </span>
            </div>
            <div className="flex-1">
              <h3 className="font-heading font-semibold text-text-primary leading-tight">
                {hoveredNode.title}
              </h3>
              <p className="text-sm text-text-secondary capitalize mt-1">
                {hoveredNode.subject} • {hoveredNode.difficulty}
              </p>
              {hoveredNode.description && (
                <p className="text-xs text-text-secondary mt-2 leading-relaxed">
                  {hoveredNode.description}
                </p>
              )}
            </div>
          </div>
          
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-sm text-text-secondary">Progress</span>
              <span className="text-sm font-medium text-text-primary">
                {Math.round(hoveredNode.progress || 0)}%
              </span>
            </div>
            
            <div className="w-full bg-surface-100 rounded-full h-2">
              <div 
                className="h-2 rounded-full transition-all duration-300"
                style={{ 
                  width: `${hoveredNode.progress || 0}%`,
                  backgroundColor: themeColors.accent
                }}
              ></div>
            </div>

            {hoveredNode.estimatedTime && (
              <div className="flex items-center justify-between">
                <span className="text-sm text-text-secondary">Est. Time</span>
                <span className="text-sm font-medium text-text-primary">
                  {hoveredNode.estimatedTime}
                </span>
              </div>
            )}

            {hoveredNode.lastAccessed && (
              <div className="flex items-center justify-between">
                <span className="text-sm text-text-secondary">Last Accessed</span>
                <span className="text-sm font-medium text-text-primary">
                  {new Date(hoveredNode.lastAccessed).toLocaleDateString()}
                </span>
              </div>
            )}
          </div>

          {hoveredNode.connections && hoveredNode.connections.length > 0 && (
            <div className="mt-3 pt-3 border-t border-border">
              <p className="text-xs text-text-secondary">
                Connected to {hoveredNode.connections.length} topic{hoveredNode.connections.length > 1 ? 's' : ''}
              </p>
            </div>
          )}
        </div>
      )}

      {/* Enhanced Controls */}
      <div className="absolute top-4 left-4 flex space-x-2">
        {/* View Mode Toggle */}
        <div className="bg-surface border border-border rounded-lg p-1 flex">
          <button
            onClick={() => setViewMode('clustered')}
            className={`px-3 py-1 rounded text-sm transition-colors ${
              viewMode === 'clustered' 
                ? 'bg-primary text-white' 
                : 'text-text-secondary hover:text-text-primary'
            }`}
          >
            Clustered
          </button>
          <button
            onClick={() => setViewMode('expanded')}
            className={`px-3 py-1 rounded text-sm transition-colors ${
              viewMode === 'expanded' 
                ? 'bg-primary text-white' 
                : 'text-text-secondary hover:text-text-primary'
            }`}
          >
            Expanded
          </button>
        </div>

        {/* Learning Style Indicator */}
        <div className="bg-surface border border-border rounded-lg px-3 py-2">
          <div className="flex items-center space-x-2">
            <Icon name="Eye" size={16} className="text-text-secondary" />
            <span className="text-sm font-caption text-text-secondary capitalize">
              {learningStyle} learner
            </span>
          </div>
        </div>
      </div>

      {/* Enhanced Zoom Controls */}
      <div className="absolute bottom-4 right-4 flex flex-col space-y-2">
        <div className="bg-surface border border-border rounded-lg p-1">
          <button 
            onClick={() => {
              const svg = d3.select(svgRef.current);
              svg.transition().duration(300).call(
                d3.zoom().transform,
                d3.zoomIdentity.scale(Math.min(zoomLevel * 1.5, 4))
              );
            }}
            className="block p-2 hover:bg-surface-50 transition-colors duration-200 rounded"
          >
            <Icon name="ZoomIn" size={16} className="text-text-primary" />
          </button>
          <button 
            onClick={() => {
              const svg = d3.select(svgRef.current);
              svg.transition().duration(300).call(
                d3.zoom().transform,
                d3.zoomIdentity.scale(Math.max(zoomLevel * 0.67, 0.3))
              );
            }}
            className="block p-2 hover:bg-surface-50 transition-colors duration-200 rounded"
          >
            <Icon name="ZoomOut" size={16} className="text-text-primary" />
          </button>
          <button 
            onClick={() => {
              const svg = d3.select(svgRef.current);
              svg.transition().duration(500).call(
                d3.zoom().transform,
                d3.zoomIdentity
              );
            }}
            className="block p-2 hover:bg-surface-50 transition-colors duration-200 rounded"
          >
            <Icon name="Home" size={16} className="text-text-primary" />
          </button>
        </div>
        
        {/* Zoom level indicator */}
        <div className="bg-surface border border-border rounded-lg px-2 py-1 text-center">
          <span className="text-xs text-text-secondary">
            {Math.round(zoomLevel * 100)}%
          </span>
        </div>
      </div>

      {/* Subject Legend */}
      {nodes.length > 0 && <div className="absolute bottom-4 left-4 bg-surface border border-border rounded-lg p-3">
        <h4 className="text-sm font-medium text-text-primary mb-2">Subjects</h4>
        <div className="space-y-1">
          {Object.entries(groupNodesBySubject(nodes)).map(([subject, subjectNodes]) => {
            const iconInfo = getEnhancedSubjectIcon(subject);
            return (
              <div key={subject} className="flex items-center space-x-2">
                <span className="text-sm" style={{ color: iconInfo.color }}>
                  {iconInfo.symbol}
                </span>
                <span className="text-xs text-text-secondary capitalize">
                  {subject} ({subjectNodes.length})
                </span>
              </div>
            );
          })}
        </div>
      </div>}
    </div>
  );
};

// Enhanced helper functions
function groupNodesBySubject(nodes) {
  return nodes.reduce((acc, node) => {
    if (!acc[node.subject]) acc[node.subject] = [];
    acc[node.subject].push(node);
    return acc;
  }, {});
}

function calculateSubjectCenters(nodesBySubject, width, height, viewMode = 'clustered') {
  const subjects = Object.keys(nodesBySubject);
  const centers = {};
  
  if (viewMode === 'overview') {
    // Tighter grid layout for overview mode
    const cols = Math.max(2, Math.ceil(Math.sqrt(subjects.length)));
    const rows = Math.ceil(subjects.length / cols);
    
    subjects.forEach((subject, index) => {
      const row = Math.floor(index / cols);
      const col = index % cols;
      
      centers[subject] = {
        x: (width * 0.2) + (width * 0.6 / cols) * col + (width * 0.6 / cols) * 0.5,
        y: (height * 0.2) + (height * 0.6 / rows) * row + (height * 0.6 / rows) * 0.5
      };
    });
  } else {
    // More spread out layout for clustered mode
    const cols = Math.ceil(Math.sqrt(subjects.length));
    const rows = Math.ceil(subjects.length / cols);
    
    subjects.forEach((subject, index) => {
      const row = Math.floor(index / cols);
      const col = index % cols;
      
      centers[subject] = {
        x: (width / (cols + 1)) * (col + 1),
        y: (height / (rows + 1)) * (row + 1)
      };
    });
  }
  
  return centers;
}

function forceCluster(centers, viewMode = 'clustered') {
  let nodes = [];
  function force(alpha) {
    const strength = viewMode === 'overview' ? 0.15 : 0.1;
    for (const d of nodes) {
      const center = centers[d.subject];
      if (center) {
        d.vx += (center.x - d.x) * alpha * strength;
        d.vy += (center.y - d.y) * alpha * strength;
      }
    }
  }
  force.initialize = function(n) { nodes = n; };
  return force;
}

function createEnhancedLinks(nodes) {
  const links = [];
  
  nodes.forEach(node => {
    // Prerequisite links
    if (node.prerequisite) {
      const prerequisiteNode = nodes.find(n => n.id === node.prerequisite);
      if (prerequisiteNode) {
        links.push({
          source: node.prerequisite,
          target: node.id,
          type: 'prerequisite',
          strength: 1
        });
      }
    }
    
    // Subject similarity links
    const sameSubjectNodes = nodes.filter(n => 
      n.subject === node.subject && 
      n.id !== node.id && 
      Math.abs(getDifficultyLevel(n.difficulty) - getDifficultyLevel(node.difficulty)) <= 1
    );
    
    sameSubjectNodes.slice(0, 2).forEach(similarNode => {
      links.push({
        source: node.id,
        target: similarNode.id,
        type: 'similarity',
        strength: 0.5
      });
    });
  });
  
  return links;
}

function getDifficultyLevel(difficulty) {
  const levels = { beginner: 1, intermediate: 2, advanced: 3 };
  return levels[difficulty] || 2;
}

function getNodeRadius(node) {
  const baseRadius = 30;
  const difficultyMultiplier = {
    beginner: 1,
    intermediate: 1.1,
    advanced: 1.2
  };
  return baseRadius * (difficultyMultiplier[node.difficulty] || 1);
}

function getNodeFill(node, themeColors) {
  if (node.completed) return themeColors.secondary;
  if (node.status === 'in-progress') return themeColors.accent;
  if (node.status === 'locked') return '#e5e7eb';
  return '#f9fafb';
}

function getNodeStroke(node, themeColors) {
  if (node.status === 'locked') return '#d1d5db';
  return themeColors.primary;
}

function getEnhancedSubjectIcon(subject) {
  const icons = {
    mathematics: { symbol: '∫', color: '#3b82f6' },
    programming: { symbol: '⟨/⟩', color: '#10b981' },
    history: { symbol: '🏛', color: '#f59e0b' },
    science: { symbol: '⚛', color: '#8b5cf6' },
    geography: { symbol: '🌍', color: '#06b6d4' },
    literature: { symbol: '📖', color: '#ec4899' },
    'art-history': { symbol: '🎨', color: '#f97316' },
    languages: { symbol: '🗣', color: '#84cc16' },
    business: { symbol: '💼', color: '#6366f1' },
    philosophy: { symbol: '💭', color: '#a855f7' },
    arts: { symbol: '🎭', color: '#f43f5e' }
  };
  return icons[subject] || { symbol: '📚', color: '#6b7280' };
}

function getConnectionColor(link, themeColors) {
  if (link.type === 'prerequisite') return themeColors.primary;
  if (link.type === 'similarity') return themeColors.secondary;
  return themeColors.accent;
}

function addProgressVisualization(group, node, themeColors) {
  const circumference = 2 * Math.PI * 25;
  const progressOffset = circumference - (node.progress / 100) * circumference;
  
  group.append('circle')
    .attr('r', 25)
    .attr('fill', 'none')
    .attr('stroke', themeColors.accent)
    .attr('stroke-width', 3)
    .attr('stroke-dasharray', circumference)
    .attr('stroke-dashoffset', progressOffset)
    .attr('stroke-linecap', 'round')
    .style('transform', 'rotate(-90deg)')
    .style('transform-origin', 'center');
}

function addDifficultyIndicator(group, node, themeColors) {
  const colors = {
    beginner: '#10b981',
    intermediate: '#f59e0b',
    advanced: '#ef4444'
  };
  
  group.append('circle')
    .attr('cx', 22)
    .attr('cy', -22)
    .attr('r', 8)
    .attr('fill', colors[node.difficulty] || '#6b7280')
    .attr('stroke', 'white')
    .attr('stroke-width', 2)
    .style('opacity', 0.9);
    
  group.append('text')
    .attr('x', 22)
    .attr('y', -22)
    .attr('text-anchor', 'middle')
    .attr('dy', '0.35em')
    .attr('font-size', '10px')
    .attr('font-weight', 'bold')
    .attr('fill', 'white')
    .text((node.difficulty || 'I')[0].toUpperCase());
}

function addEnhancedTitle(group, node) {
  const raw = node.title || '';
  const title = raw.length > 20 ? raw.substring(0, 20) + '...' : raw;
  
  group.append('text')
    .attr('text-anchor', 'middle')
    .attr('dy', '-45px')
    .attr('font-size', '14px')
    .attr('font-weight', '500')
    .attr('fill', '#1f2937')
    .text(title);
}

function addStatusIndicators(group, node, themeColors) {
  if (node.status === 'completed') {
    group.append('circle')
      .attr('cx', -22)
      .attr('cy', -22)
      .attr('r', 8)
      .attr('fill', '#10b981')
      .attr('stroke', 'white')
      .attr('stroke-width', 2);
      
    group.append('text')
      .attr('x', -22)
      .attr('y', -22)
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .attr('font-size', '10px')
      .attr('fill', 'white')
      .text('✓');
  }
}

function enhanceNodeOnHover(selection, node, themeColors) {
  selection.select('circle')
    .transition()
    .duration(200)
    .attr('r', getNodeRadius(node) * 1.15)
    .style('filter', 'drop-shadow(0 6px 20px rgba(0, 0, 0, 0.25))');
}

function resetNodeFromHover(selection, node) {
  selection.select('circle')
    .transition()
    .duration(200)
    .attr('r', getNodeRadius(node))
    .style('filter', 'drop-shadow(0 4px 12px rgba(0, 0, 0, 0.15))');
}

function drawSubjectAreas(container, subjectCenters, themeColors) {
  Object.entries(subjectCenters).forEach(([subject, center]) => {
    const iconInfo = getEnhancedSubjectIcon(subject);
    
    container.append('circle')
      .attr('cx', center.x)
      .attr('cy', center.y)
      .attr('r', 80)
      .attr('fill', iconInfo.color)
      .attr('opacity', 0.05)
      .attr('stroke', iconInfo.color)
      .attr('stroke-width', 1)
      .attr('stroke-opacity', 0.1);
      
    container.append('text')
      .attr('x', center.x)
      .attr('y', center.y - 60)
      .attr('text-anchor', 'middle')
      .attr('font-size', '12px')
      .attr('font-weight', '500')
      .attr('fill', iconInfo.color)
      .attr('opacity', 0.6)
      .text(subject.charAt(0).toUpperCase() + subject.slice(1));
  });
}

export default MindMapVisualization;