import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';

const AchievementNotifications = ({ achievements, themeColors }) => {
  const [visibleAchievements, setVisibleAchievements] = useState([]);
  const [dismissedIds, setDismissedIds] = useState(new Set());

  useEffect(() => {
    // Show new achievements that haven't been dismissed
    const newAchievements = achievements.filter(
      achievement => achievement.unlocked && !dismissedIds.has(achievement.id)
    );
    
    if (newAchievements.length > 0) {
      setVisibleAchievements(newAchievements.slice(0, 3)); // Show max 3 at once
    }
  }, [achievements, dismissedIds]);

  const handleDismiss = (achievementId) => {
    setDismissedIds(prev => new Set([...prev, achievementId]));
    setVisibleAchievements(prev => prev.filter(a => a.id !== achievementId));
  };

  const getAchievementIcon = (type) => {
    const icons = {
      weekly: 'Award',
      streak: 'Flame',
      milestone: 'Trophy',
      collaboration: 'Users',
      mastery: 'Star'
    };
    return icons[type] || 'Award';
  };

  const getAchievementColor = (type) => {
    const colors = {
      weekly: themeColors.primary,
      streak: themeColors.accent,
      milestone: '#FFD700',
      collaboration: themeColors.secondary,
      mastery: '#9333EA'
    };
    return colors[type] || themeColors.primary;
  };

  const formatTimeAgo = (timestamp) => {
    const now = new Date();
    const diff = now - timestamp;
    const minutes = Math.floor(diff / 60000);
    
    if (minutes < 1) return 'Just now';
    if (minutes < 60) return `${minutes}m ago`;
    
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return `${hours}h ago`;
    
    const days = Math.floor(hours / 24);
    return `${days}d ago`;
  };

  if (visibleAchievements.length === 0) return null;

  return (
    <div className="fixed top-20 right-4 z-50 space-y-3 max-w-sm">
      {visibleAchievements.map((achievement, index) => (
        <div
          key={achievement.id}
          className="bg-surface border border-border rounded-lg shadow-warm-lg p-4 animate-slide-up"
          style={{ animationDelay: `${index * 0.1}s` }}
        >
          <div className="flex items-start space-x-3">
            {/* Achievement Icon */}
            <div 
              className="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0"
              style={{ backgroundColor: `${getAchievementColor(achievement.type)}20` }}
            >
              <Icon 
                name={getAchievementIcon(achievement.type)} 
                size={20} 
                style={{ color: getAchievementColor(achievement.type) }}
              />
            </div>

            {/* Achievement Content */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between mb-1">
                <h3 className="font-heading font-semibold text-text-primary text-sm">
                  {achievement.title}
                </h3>
                <button
                  onClick={() => handleDismiss(achievement.id)}
                  className="text-text-tertiary hover:text-text-secondary transition-colors duration-200"
                >
                  <Icon name="X" size={14} />
                </button>
              </div>
              
              <p className="text-sm text-text-secondary mb-2">
                {achievement.description}
              </p>
              
              <div className="flex items-center justify-between">
                <span className="text-xs text-text-tertiary">
                  {formatTimeAgo(achievement.timestamp)}
                </span>
                <div className="flex items-center space-x-1">
                  <Icon name="Sparkles" size={12} className="text-accent" />
                  <span className="text-xs font-medium text-accent">+50 XP</span>
                </div>
              </div>
            </div>
          </div>

          {/* Achievement Progress Bar */}
          <div className="mt-3 pt-3 border-t border-border">
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs text-text-secondary">Achievement Progress</span>
              <span className="text-xs font-medium text-text-primary">100%</span>
            </div>
            <div className="w-full bg-surface-100 rounded-full h-1.5">
              <div 
                className="h-1.5 rounded-full transition-all duration-1000 ease-out"
                style={{ 
                  width: '100%',
                  backgroundColor: getAchievementColor(achievement.type)
                }}
              ></div>
            </div>
          </div>

          {/* Celebration Animation */}
          <div className="absolute inset-0 pointer-events-none overflow-hidden rounded-lg">
            {[...Array(6)].map((_, i) => (
              <div
                key={i}
                className="absolute w-1 h-1 rounded-full animate-ping"
                style={{
                  backgroundColor: getAchievementColor(achievement.type),
                  left: `${20 + i * 15}%`,
                  top: `${10 + (i % 2) * 20}%`,
                  animationDelay: `${i * 0.2}s`,
                  animationDuration: '2s'
                }}
              ></div>
            ))}
          </div>
        </div>
      ))}

      {/* Achievement Summary */}
      {visibleAchievements.length > 0 && (
        <div className="bg-gradient-to-r from-primary-50 to-secondary-50 border border-primary-100 rounded-lg p-3 mt-3">
          <div className="flex items-center space-x-2">
            <Icon name="Trophy" size={16} className="text-primary" />
            <span className="text-sm font-medium text-text-primary">
              {visibleAchievements.length} new achievement{visibleAchievements.length > 1 ? 's' : ''}!
            </span>
          </div>
          <p className="text-xs text-text-secondary mt-1">
            Keep up the great learning momentum!
          </p>
        </div>
      )}
    </div>
  );
};

export default AchievementNotifications;